import ipaddress

allowed_ranges = [ipaddress.ip_network(cidr) for cidr in ("203.0.113.0/24", "198.51.100.128/25")]

def request_allowed(ip):
    address = ipaddress.ip_address(ip)
    return any(address in network for network in allowed_ranges)

requests = ["203.0.113.42", "198.51.100.200", "192.0.2.10", "198.51.100.5"]
for ip in requests:
    print(ip, "->", "ALLOW" if request_allowed(ip) else "DENY")
